// City Camp Hybrid PHEV n'a pas de colonne dédiée dans le tarif options : il partage les mêmes
// équipements que City Camp (même carrosserie), donc on duplique son statut de compatibilité.
CAMPEREVE_OPTIONS.forEach((o) => {
  if (o.compat && o.compat["cve_citycamp"] !== undefined) {
    o.compat["cve_citycamp_hybrid"] = o.compat["cve_citycamp"];
  }
});

